const session=JSON.parse(localStorage.getItem("cheers_session")||"null");
if(!session)location.replace("/login.html");
const money=new Intl.NumberFormat("es-CO",{style:"currency",currency:"COP",maximumFractionDigits:0});
const view=document.querySelector("#adminView"),title=document.querySelector("#viewTitle");
const labels={dashboard:"Resumen.",pos:"Caja · Facturar.",sales:"Facturas y ventas.",inventory:"Inventario y productos.",tables:"QR y mesas.",settings:"Perfil del local."};
let panel="dashboard",catalog={products:[],inventory:[],tables:[],inventoryMoves:[],tableRequests:[]},cart=[],category="Todos",query="",method="Efectivo",inventoryMode="products",inventoryQuery="",inventoryCategory="Todos",editingProduct=null;
const escape=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char]));
const api=(path,options={})=>fetch(path,{...options,headers:{"Content-Type":"application/json",Authorization:`Bearer ${session?.token||""}`,...options.headers}}).then(async response=>{const isJson=(response.headers.get("content-type")||"").includes("application/json"),data=isJson?await response.json():{error:await response.text()};if(!response.ok)throw new Error(data.error||"No pudimos completar la acción.");return data});
const photo=file=>new Promise((resolve,reject)=>{if(!file?.size)return resolve("");if(file.size>2_500_000)return reject(new Error("La foto debe pesar menos de 2,5 MB."));const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{const scale=Math.min(1,1280/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext("2d",{alpha:false}).drawImage(image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);canvas.toBlob(blob=>{if(!blob)return reject(new Error("No pudimos preparar la foto."));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)},"image/jpeg",.78)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("No pudimos leer la foto."))};image.src=url});

function setNav(){document.querySelectorAll(".nav-item").forEach(button=>button.classList.toggle("active",button.dataset.panel===panel));title.textContent=labels[panel]||"Cheers."}
async function loadCatalog(){catalog=await api("/api/catalog");return catalog}
function stockInfo(product){if(!product.recipe?.length)return {count:null,label:"Sin receta",className:"stock-unknown"};const amounts=product.recipe.map(line=>{const ingredient=catalog.inventory.find(item=>item.id===line.ingredientId);return ingredient?Math.floor(Number(ingredient.stock)/Number(line.amount)):0});const count=Math.max(0,Math.min(...amounts));return {count,label:count?`${count} ventas posibles`:"Agotado",className:count?"stock-ok":"stock-empty"}}
function productForm(product={}){const recipe=product.recipe?.length?product.recipe:[{}],options=(product.options||[]).join(", ");return `<form id="productForm" class="quick-form"><strong>${product.id?"Editar producto":"Agregar producto"}</strong><input name="id" type="hidden" value="${escape(product.id||"")}"><input name="name" value="${escape(product.name||"")}" placeholder="Nombre" required><input name="price" value="${product.price||""}" type="number" min="1" placeholder="Precio" required><textarea name="description" placeholder="Descripción">${escape(product.description||"")}</textarea><select name="category">${["cafe","comida","cocteles","bebidas","cervezas","licores","especiales"].map(item=>`<option value="${item}" ${product.category===item?"selected":""}>${item}</option>`).join("")}</select><textarea name="options" placeholder="Opciones separadas por coma. Ej: Sin hielo, Extra shot">${escape(options)}</textarea><label class="photo-input">${product.id?"Cambiar foto":"Foto"}<input name="photo" type="file" accept="image/*"></label><label class="option-chip"><input name="active" type="checkbox" ${product.active!==false?"checked":""}> Visible en el menú</label><div class="recipe-builder"><div class="recipe-title"><b>Receta e inventario</b><button id="addRecipe" type="button" class="text-button">+ Insumo</button></div><p>Esto se descuenta cada vez que se vende.</p><div id="recipeLines">${recipe.map(recipeLine).join("")}</div></div><button class="primary-button">${product.id?"Guardar cambios":"Crear producto"}</button></form>`}
function recipeLine(line={}){return `<div class="recipe-line"><select data-recipe-ingredient><option value="">Selecciona insumo</option>${catalog.inventory.map(item=>`<option value="${item.id}" ${line.ingredientId===item.id?"selected":""}>${escape(item.name)} (${escape(item.unit)})</option>`).join("")}</select><input data-recipe-amount value="${line.amount||""}" type="number" min="0.01" step="0.01" placeholder="Cantidad"><button type="button" class="remove-recipe">×</button></div>`}

async function renderDashboard(){const [dashboard]=await Promise.all([api("/api/dashboard"),loadCatalog()]);view.innerHTML=`<div class="metric-grid"><article><span>Ventas hoy</span><strong>${money.format(dashboard.sales)}</strong></article><article><span>Pedidos</span><strong>${dashboard.orders}</strong></article><article><span>Activos</span><strong>${dashboard.active}</strong></article><article><span>Insumos bajos</span><strong>${dashboard.lowStock.length}</strong></article></div><section class="admin-section"><div class="admin-section-head"><h2>Atención del día</h2><button class="text-button" data-go="tables">Ver mesas</button></div><p class="empty-state">${catalog.tableRequests.length?`${catalog.tableRequests.length} solicitud(es) de mesa esperando atención.`:"No hay solicitudes pendientes."}</p></section>${dashboard.lowStock.length?`<section class="admin-section"><div class="admin-section-head"><h2>Reponer pronto</h2><button class="text-button" data-go="inventory">Inventario</button></div><div class="data-list">${dashboard.lowStock.map(item=>`<div class="data-row"><div><strong>${escape(item.name)}</strong><span>${item.stock} disponibles · mínimo ${item.minimum_stock}</span></div><strong class="low-stock">Bajo</strong></div>`).join("")}</div></section>`:""}`}
function posProducts(){return catalog.products.filter(product=>product.active&&product.available&&(category==="Todos"||product.category===category)&&product.name.toLocaleLowerCase().includes(query))}
async function renderPos(){await loadCatalog();const [cash,report]=await Promise.all([api("/api/cash/current"),api("/api/reports/sales")]);const total=cart.reduce((sum,item)=>sum+item.price*item.quantity,0),categories=["Todos",...new Set(catalog.products.filter(item=>item.active).map(item=>item.category))];view.innerHTML=`<section class="cash-strip"><div><p class="eyebrow">Turno de caja</p><strong>${cash.session?"Caja abierta":"Caja cerrada"}</strong><span>${cash.session?`Fondo: ${money.format(cash.session.openingAmount)}`:"Abre el turno antes de facturar"}</span></div><div class="cash-strip-actions"><button class="text-button" data-cash="${cash.session?"close":"open"}">${cash.session?"Cerrar turno":"Abrir turno"}</button><span>Hoy: ${money.format(report.today)}</span></div></section><section class="pos-layout"><div class="pos-catalog"><div class="pos-toolbar"><input id="posSearch" value="${escape(query)}" placeholder="Buscar: escribe c, café, coca cola…"><div class="pos-categories">${categories.map(item=>`<button class="pos-category ${category===item?"active":""}" data-pos-category="${item}">${escape(item)}</button>`).join("")}</div></div><div class="pos-products">${posProducts().map(product=>`<button class="pos-product" data-add="${product.id}">${product.imageUrl?`<span class="pos-thumb" style="background-image:url('${product.imageUrl}')"></span>`:""}<span><b>${escape(product.name)}</b><small>${money.format(product.price)}</small></span></button>`).join("")||'<p class="empty-state">No hay coincidencias.</p>'}</div></div><aside class="pos-ticket"><p class="eyebrow">Factura nueva</p><h2>Venta</h2><div class="pos-cart">${cart.map(item=>`<div class="pos-line"><div><b>${escape(item.name)}</b><small>${money.format(item.price)}</small></div><div class="pos-qty"><button data-dec="${item.id}">−</button><span>${item.quantity}</span><button data-inc="${item.id}">+</button></div><strong>${money.format(item.price*item.quantity)}</strong></div>`).join("")||'<p class="empty-state">Toca un producto para agregarlo.</p>'}</div><div class="pos-total"><span>Total</span><strong>${money.format(total)}</strong></div><p class="eyebrow">Medio de pago</p><div class="method-grid">${["Efectivo","Tarjeta","Nequi","Transferencia"].map(item=>`<button class="method-button ${method===item?"active":""}" data-method="${item}">${item}</button>`).join("")}</div><button class="checkout-button" id="charge" ${cart.length&&cash.session?"":"disabled"}>${cash.session?"Cobrar y facturar":"Abre caja para facturar"}</button></aside></section>`}
async function renderSales(){const report=await api("/api/reports/sales");view.innerHTML=`<div class="metric-grid"><article><span>Hoy</span><strong>${money.format(report.today)}</strong></article><article><span>Semana</span><strong>${money.format(report.week)}</strong></article><article><span>Mes</span><strong>${money.format(report.month)}</strong></article><article><span>Facturas</span><strong>${report.invoices.length}</strong></article></div><section class="admin-section"><div class="admin-section-head"><h2>Facturas creadas</h2><span>Venta y método de pago</span></div><div class="data-list">${report.invoices.map(invoice=>`<div class="data-row"><div><strong>${escape(invoice.order.code)}</strong><span>${escape(invoice.order.items.map(item=>`${item.quantity}× ${item.name}`).join(", "))} · ${escape(invoice.method)}</span></div><div><strong>${money.format(invoice.amount)}</strong><button class="text-button" data-print-invoice="${invoice.order.id}">Imprimir</button><button class="text-button" data-cancel-sale="${invoice.order.id}">Anular</button></div></div>`).join("")||'<p class="empty-state">Todavía no hay facturas.</p>'}</div></section>`}
async function renderInventory(){await loadCatalog();const categories=["Todos",...new Set(catalog.products.map(product=>product.category))],products=catalog.products.filter(product=>(inventoryCategory==="Todos"||product.category===inventoryCategory)&&product.name.toLocaleLowerCase().includes(inventoryQuery));const movements=catalog.inventoryMoves.slice(0,12);view.innerHTML=`<section class="inventory-head"><div class="inventory-switch"><button class="inventory-mode ${inventoryMode==="products"?"active":""}" data-inventory-mode="products">Productos</button><button class="inventory-mode ${inventoryMode==="ingredients"?"active":""}" data-inventory-mode="ingredients">Insumos</button></div><input id="inventorySearch" placeholder="Buscar producto o insumo…" value="${escape(inventoryQuery)}"></section>${inventoryMode==="products"?`<section class="inventory-actions"><div><p class="eyebrow">Control de productos</p><h2>Nombre, precio y cantidad</h2></div><button class="primary-button" data-new-product>+ Agregar producto</button></section>${editingProduct!==null?`<div class="inventory-editor">${productForm(catalog.products.find(product=>product.id===editingProduct)||{})}<button class="text-button" data-cancel-editor>Cancelar</button></div>`:""}<div class="pos-categories inventory-categories">${categories.map(item=>`<button class="pos-category ${inventoryCategory===item?"active":""}" data-inventory-category="${item}">${escape(item)}</button>`).join("")}</div><section class="inventory-product-grid">${products.map(product=>{const status=stockInfo(product);return `<article class="inventory-product"><div class="inventory-image" ${product.imageUrl?`style="background-image:url('${product.imageUrl}')"`:""}></div><div><p>${escape(product.category)}</p><h3>${escape(product.name)}</h3><dl><div><dt>Precio</dt><dd>${money.format(product.price)}</dd></div><div><dt>Cantidad</dt><dd class="${status.className}">${status.count===null?"Sin receta":status.count}</dd></div></dl><span class="${status.className}">${escape(status.label)}</span><button class="text-button" data-edit-product="${product.id}">Editar producto / receta</button></div></article>`}).join("")||'<p class="empty-state">No hay productos con esa búsqueda.</p>'}</section>`:`<form id="ingredientForm" class="quick-form"><strong>Nuevo insumo</strong><input name="name" placeholder="Nombre" required><select name="unit"><option value="und">Unidades</option><option value="g">Gramos</option><option value="ml">Mililitros</option></select><input name="stock" type="number" min="0" placeholder="Existencia" required><input name="minimum" type="number" min="0" placeholder="Mínimo" required><input name="cost" type="number" min="0" placeholder="Costo unitario"><button class="primary-button">Agregar insumo</button></form><section class="admin-section"><div class="admin-section-head"><h2>Insumos</h2><span>Entradas y ajustes registrados</span></div><div class="data-list">${catalog.inventory.filter(item=>item.name.toLocaleLowerCase().includes(inventoryQuery)).map(item=>`<div class="data-row"><div><strong>${escape(item.name)}</strong><span>${item.stock} ${escape(item.unit)} · mínimo ${item.minimum}</span></div><div><button class="text-button" data-restock="${item.id}">+ Entrada</button><button class="text-button" data-edit-ingredient="${item.id}">Editar</button></div></div>`).join("")||'<p class="empty-state">No hay insumos con esa búsqueda.</p>'}</div></section><section class="admin-section"><div class="admin-section-head"><h2>Últimos movimientos</h2><span>${movements.length}</span></div><div class="data-list">${movements.map(move=>{const item=catalog.inventory.find(ingredient=>ingredient.id===move.ingredientId);return `<div class="data-row"><div><strong>${escape(item?.name||"Insumo")}</strong><span>${escape(move.reason)} · ${new Date(move.createdAt).toLocaleString("es-CO")}</span></div><strong class="${move.quantity<0?"low-stock":"stock-ok"}">${move.quantity>0?"+":""}${move.quantity} ${escape(item?.unit||"")}</strong></div>`}).join("")||'<p class="empty-state">Aún no hay movimientos.</p>'}</div></section>`}`
}
async function renderTables(){await loadCatalog();view.innerHTML=`<section class="admin-section"><div class="admin-section-head"><h2>Solicitudes de mesas</h2><span>${catalog.tableRequests.length} pendientes</span></div><div class="data-list">${catalog.tableRequests.map(request=>`<div class="data-row"><div><strong>Mesa ${String(request.tableId).padStart(2,"0")} · ${escape(request.type)}</strong><span>${escape(request.note||"Sin nota")}</span></div><button class="text-button" data-resolve="${request.id}">Atender</button></div>`).join("")||'<p class="empty-state">No hay solicitudes pendientes.</p>'}</div></section><section class="admin-section"><div class="admin-section-head"><h2>QR imprimibles</h2><span>Uno por mesa</span></div><div class="table-grid">${catalog.tables.map(table=>`<article class="qr-card"><strong>${escape(table.name)}</strong><code>${location.origin}/?table=${table.id}</code><button class="copy-link" data-print-table="${table.id}">Imprimir tarjeta</button></article>`).join("")}</div></section>`}
async function renderSettings(){await loadCatalog();const locationData=catalog.location||{};view.innerHTML=`<section class="admin-section"><p class="eyebrow">Información pública</p><h2>Perfil de Cheers</h2><form id="settingsForm" class="quick-form"><input name="name" value="${escape(locationData.name||"Cheers")}" placeholder="Nombre del local"><input name="hours" value="${escape(locationData.hours||"")}" placeholder="Horario"><input name="address" value="${escape(locationData.address||"")}" placeholder="Dirección"><input name="whatsapp" value="${escape(locationData.whatsapp||"")}" placeholder="WhatsApp con indicativo"><input name="instagram" value="${escape(locationData.instagram||"")}" placeholder="Instagram"><button class="primary-button">Guardar perfil público</button></form></section><section class="admin-section"><h2>App de Cheers</h2><p class="empty-state">En teléfono: abre el menú y usa “Instalar app” o “Agregar a pantalla de inicio”.</p></section>`}
async function render(){setNav();if(panel==="dashboard")return renderDashboard();if(panel==="pos")return renderPos();if(panel==="sales")return renderSales();if(panel==="inventory")return renderInventory();if(panel==="tables")return renderTables();if(panel==="settings")return renderSettings()}
function openInvoice(order){const win=window.open("","_blank");win.document.write(`<title>Factura ${escape(order.code)}</title><style>body{font-family:Arial;max-width:380px;margin:30px auto;padding:20px}h1{margin-bottom:4px}div{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #ddd}strong{font-size:20px}</style><h1>CHEERS</h1><p>Factura ${escape(order.code)}</p>${order.items.map(item=>`<div><span>${item.quantity}× ${escape(item.name)}</span><span>${money.format(item.quantity*item.unitPrice)}</span></div>`).join("")}<p><strong>Total: ${money.format(order.total)}</strong></p><p>Gracias por visitarnos.</p>`);win.print()}
document.addEventListener("click",async event=>{try{const nav=event.target.closest(".nav-item");if(nav){panel=nav.dataset.panel;return render()}if(event.target.closest("#logoutButton")){localStorage.removeItem("cheers_session");location.href="/login.html";return}const go=event.target.closest("[data-go]");if(go){panel=go.dataset.go;return render()}const cash=event.target.closest("[data-cash]");if(cash){const amount=prompt(cash.dataset.cash==="open"?"Fondo inicial de caja:":"Efectivo contado al cerrar:");if(amount===null)return;const result=await api(`/api/cash/${cash.dataset.cash}`,{method:"POST",body:JSON.stringify({amount})});if(result.summary)alert(`Esperado: ${money.format(result.summary.expected)}\nContado: ${money.format(result.summary.counted)}\nDiferencia: ${money.format(result.summary.difference)}`);return renderPos()}const add=event.target.closest("[data-add]");if(add){const product=catalog.products.find(item=>item.id===add.dataset.add),line=cart.find(item=>item.id===product.id);line?line.quantity++:cart.push({...product,quantity:1});return renderPos()}const quantity=event.target.closest("[data-inc],[data-dec]");if(quantity){const id=quantity.dataset.inc||quantity.dataset.dec,line=cart.find(item=>item.id===id);line.quantity+=quantity.dataset.inc?1:-1;if(line.quantity<1)cart=cart.filter(item=>item!==line);return renderPos()}const posCategory=event.target.closest("[data-pos-category]");if(posCategory){category=posCategory.dataset.posCategory;return renderPos()}const methodButton=event.target.closest("[data-method]");if(methodButton){method=methodButton.dataset.method;return renderPos()}if(event.target.closest("#charge")){const order=await api("/api/pos/sale",{method:"POST",body:JSON.stringify({method,items:cart.map(item=>({productId:item.id,quantity:item.quantity}))})});cart=[];alert(`Factura ${order.order.code} creada.`);openInvoice(order.order);return renderPos()}const mode=event.target.closest("[data-inventory-mode]");if(mode){inventoryMode=mode.dataset.inventoryMode;return renderInventory()}const invCategory=event.target.closest("[data-inventory-category]");if(invCategory){inventoryCategory=invCategory.dataset.inventoryCategory;return renderInventory()}if(event.target.closest("[data-new-product]")){editingProduct="";inventoryMode="products";return renderInventory()}const editProduct=event.target.closest("[data-edit-product]");if(editProduct){editingProduct=editProduct.dataset.editProduct;inventoryMode="products";return renderInventory()}if(event.target.closest("[data-cancel-editor]")){editingProduct=null;return renderInventory()}if(event.target.closest("#addRecipe")){document.querySelector("#recipeLines")?.insertAdjacentHTML("beforeend",recipeLine());return}const remove=event.target.closest(".remove-recipe");if(remove&&document.querySelectorAll(".recipe-line").length>1){remove.closest(".recipe-line").remove();return}const restock=event.target.closest("[data-restock]");if(restock){const ingredient=catalog.inventory.find(item=>item.id===restock.dataset.restock),quantity=prompt(`Cantidad que ingresó de ${ingredient.name}:`);if(quantity!==null&&quantity!=="")await api(`/api/inventory/${ingredient.id}/restock`,{method:"PATCH",body:JSON.stringify({quantity})});return renderInventory()}const editIngredient=event.target.closest("[data-edit-ingredient]");if(editIngredient){const ingredient=catalog.inventory.find(item=>item.id===editIngredient.dataset.editIngredient),stock=prompt(`Existencia actual de ${ingredient.name}:`,ingredient.stock);if(stock!==null)await api(`/api/inventory/${ingredient.id}`,{method:"PATCH",body:JSON.stringify({...ingredient,stock})});return renderInventory()}const resolve=event.target.closest("[data-resolve]");if(resolve){await api(`/api/table-requests/${resolve.dataset.resolve}/resolve`,{method:"PATCH"});return renderTables()}const cancel=event.target.closest("[data-cancel-sale]");if(cancel){if(confirm("¿Anular esta venta? Se devolverá el inventario."))await api(`/api/orders/${cancel.dataset.cancelSale}/status`,{method:"PATCH",body:JSON.stringify({status:"cancelled"})});return renderSales()}const print=event.target.closest("[data-print-invoice]");if(print){const report=await api("/api/reports/sales"),invoice=report.invoices.find(item=>item.order.id===print.dataset.printInvoice);if(invoice)openInvoice(invoice.order)}const printTable=event.target.closest("[data-print-table]");if(printTable){const link=`${location.origin}/?table=${printTable.dataset.printTable}`,qr=`https://api.qrserver.com/v1/create-qr-code/?size=350x350&data=${encodeURIComponent(link)}`,win=window.open("","_blank");win.document.write(`<title>Cheers · Mesa ${printTable.dataset.printTable}</title><style>body{font-family:Arial;text-align:center;padding:30px}img{width:260px}</style><h1>CHEERS</h1><h2>Mesa ${String(printTable.dataset.printTable).padStart(2,"0")}</h2><img src="${qr}"><p>Escanea para pedir</p>`);win.print()}}catch(error){alert(error.message)}});
document.addEventListener("input",event=>{if(event.target.id==="posSearch"){query=event.target.value.toLocaleLowerCase();renderPos()}if(event.target.id==="inventorySearch"){inventoryQuery=event.target.value.toLocaleLowerCase();renderInventory()}});
document.addEventListener("submit",async event=>{if(!event.target.matches("#productForm,#ingredientForm,#settingsForm"))return;event.preventDefault();try{const form=new FormData(event.target),data=Object.fromEntries(form);if(event.target.id==="ingredientForm"){await api("/api/inventory",{method:"POST",body:JSON.stringify(data)});return renderInventory()}if(event.target.id==="settingsForm"){await api("/api/settings",{method:"PATCH",body:JSON.stringify(data)});alert("Perfil público actualizado.");return renderSettings()}const imageUrl=await photo(form.get("photo")),recipe=[...event.target.querySelectorAll(".recipe-line")].map(line=>({ingredientId:line.querySelector("[data-recipe-ingredient]").value,amount:Number(line.querySelector("[data-recipe-amount]").value)})).filter(item=>item.ingredientId&&item.amount>0),options=String(data.options||"").split(",").map(item=>item.trim()).filter(Boolean),body={...data,active:form.get("active")==="on",recipe,options};if(data.id){await api(`/api/products/${data.id}`,{method:"PATCH",body:JSON.stringify(body)});if(imageUrl)await api(`/api/products/${data.id}/image`,{method:"POST",body:JSON.stringify({imageUrl})})}else await api("/api/products",{method:"POST",body:JSON.stringify({...body,imageUrl})});editingProduct=null;return renderInventory()}catch(error){alert(error.message)}});
/* V4: interacción instantánea. El catálogo se conserva durante el turno y solo se actualiza tras una operación real. */
let posMeta={cash:{session:null},report:{today:0},updated:0},inventoryUpdated=0;
async function refreshPosData(force=false){if(force||!posMeta.updated||Date.now()-posMeta.updated>30000){const [fresh,cash,report]=await Promise.all([api("/api/catalog"),api("/api/cash/current"),api("/api/reports/sales")]);catalog=fresh;posMeta={cash,report,updated:Date.now()}}}
function paintPos(){const cash=posMeta.cash,report=posMeta.report,total=cart.reduce((sum,item)=>sum+item.price*item.quantity,0),categories=["Todos",...new Set(catalog.products.filter(item=>item.active).map(item=>item.category))];view.innerHTML=`<section class="cash-strip"><div><p class="eyebrow">Turno de caja</p><strong>${cash.session?"Caja abierta":"Caja cerrada"}</strong><span>${cash.session?`Fondo: ${money.format(cash.session.openingAmount)}`:"Abre el turno antes de facturar"}</span></div><div class="cash-strip-actions"><button class="text-button" data-cash="${cash.session?"close":"open"}">${cash.session?"Cerrar turno":"Abrir turno"}</button><span>Hoy: ${money.format(report.today||0)}</span></div></section><section class="pos-layout"><div class="pos-catalog"><div class="pos-toolbar"><input id="posSearch" value="${escape(query)}" placeholder="Buscar: escribe c, café, coca cola…"><div class="pos-categories">${categories.map(item=>`<button class="pos-category ${category===item?"active":""}" data-pos-category="${item}">${escape(item)}</button>`).join("")}</div></div><div class="pos-products">${posProducts().map(product=>`<button class="pos-product" data-add="${product.id}">${product.imageUrl?`<span class="pos-thumb" style="background-image:url('${product.imageUrl}')"></span>`:""}<span><b>${escape(product.name)}</b><small>${money.format(product.price)}</small></span></button>`).join("")||'<p class="empty-state">No hay coincidencias.</p>'}</div></div><aside class="pos-ticket"><p class="eyebrow">Factura nueva</p><h2>Venta</h2><div class="pos-cart">${cart.map(item=>`<div class="pos-line"><div><b>${escape(item.name)}</b><small>${money.format(item.price)}</small></div><div class="pos-qty"><button data-dec="${item.id}">−</button><span>${item.quantity}</span><button data-inc="${item.id}">+</button></div><strong>${money.format(item.price*item.quantity)}</strong></div>`).join("")||'<p class="empty-state">Toca un producto para agregarlo.</p>'}</div><div class="pos-total"><span>Total</span><strong>${money.format(total)}</strong></div><p class="eyebrow">Medio de pago</p><div class="method-grid">${["Efectivo","Tarjeta","Nequi","Transferencia"].map(item=>`<button class="method-button ${method===item?"active":""}" data-method="${item}">${item}</button>`).join("")}</div><button class="checkout-button" id="charge" ${cart.length&&cash.session?"":"disabled"}>${cash.session?"Cobrar y facturar":"Abre caja para facturar"}</button></aside></section>`}
async function renderPos(force=false){await refreshPosData(force);paintPos()}
async function renderInventory(force=false){if(force||!inventoryUpdated||Date.now()-inventoryUpdated>30000){await loadCatalog();inventoryUpdated=Date.now()}const categories=["Todos",...new Set(catalog.products.map(product=>product.category))],products=catalog.products.filter(product=>(inventoryCategory==="Todos"||product.category===inventoryCategory)&&product.name.toLocaleLowerCase().includes(inventoryQuery)),movements=catalog.inventoryMoves.slice(0,12);view.innerHTML=`<section class="inventory-head"><div class="inventory-switch"><button class="inventory-mode ${inventoryMode==="products"?"active":""}" data-inventory-mode="products">Productos</button><button class="inventory-mode ${inventoryMode==="ingredients"?"active":""}" data-inventory-mode="ingredients">Insumos</button></div><input id="inventorySearch" placeholder="Buscar producto o insumo…" value="${escape(inventoryQuery)}"></section>${inventoryMode==="products"?`<section class="inventory-actions"><div><p class="eyebrow">Control de productos</p><h2>Nombre, precio y cantidad</h2></div><button class="primary-button" data-new-product>+ Agregar producto</button></section>${editingProduct!==null?`<div class="inventory-editor">${productForm(catalog.products.find(product=>product.id===editingProduct)||{})}<button class="text-button" data-cancel-editor>Cancelar</button></div>`:""}<div class="pos-categories inventory-categories">${categories.map(item=>`<button class="pos-category ${inventoryCategory===item?"active":""}" data-inventory-category="${item}">${escape(item)}</button>`).join("")}</div><section class="inventory-product-grid">${products.map(product=>{const status=stockInfo(product);return `<article class="inventory-product"><div class="inventory-image" ${product.imageUrl?`style="background-image:url('${product.imageUrl}')"`:""}></div><div><p>${escape(product.category)}</p><h3>${escape(product.name)}</h3><dl><div><dt>Precio</dt><dd>${money.format(product.price)}</dd></div><div><dt>Cantidad</dt><dd class="${status.className}">${status.count===null?"Sin receta":status.count}</dd></div></dl><span class="${status.className}">${escape(status.label)}</span><button class="text-button" data-edit-product="${product.id}">Editar producto / receta</button></div></article>`}).join("")||'<p class="empty-state">No hay productos con esa búsqueda.</p>'}</section>`:`<form id="ingredientForm" class="quick-form"><strong>Nuevo insumo</strong><input name="name" placeholder="Nombre" required><select name="unit"><option value="und">Unidades</option><option value="g">Gramos</option><option value="ml">Mililitros</option></select><input name="stock" type="number" min="0" placeholder="Existencia" required><input name="minimum" type="number" min="0" placeholder="Mínimo" required><input name="cost" type="number" min="0" placeholder="Costo unitario"><button class="primary-button">Agregar insumo</button></form><section class="admin-section"><div class="admin-section-head"><h2>Insumos</h2><span>Entradas y ajustes registrados</span></div><div class="data-list">${catalog.inventory.filter(item=>item.name.toLocaleLowerCase().includes(inventoryQuery)).map(item=>`<div class="data-row"><div><strong>${escape(item.name)}</strong><span>${item.stock} ${escape(item.unit)} · mínimo ${item.minimum}</span></div><div><button class="text-button" data-restock="${item.id}">+ Entrada</button><button class="text-button" data-edit-ingredient="${item.id}">Editar</button></div></div>`).join("")||'<p class="empty-state">No hay insumos con esa búsqueda.</p>'}</div></section><section class="admin-section"><div class="admin-section-head"><h2>Últimos movimientos</h2><span>${movements.length}</span></div><div class="data-list">${movements.map(move=>{const item=catalog.inventory.find(ingredient=>ingredient.id===move.ingredientId);return `<div class="data-row"><div><strong>${escape(item?.name||"Insumo")}</strong><span>${escape(move.reason)} · ${new Date(move.createdAt).toLocaleString("es-CO")}</span></div><strong class="${move.quantity<0?"low-stock":"stock-ok"}">${move.quantity>0?"+":""}${move.quantity} ${escape(item?.unit||"")}</strong></div>`}).join("")||'<p class="empty-state">Aún no hay movimientos.</p>'}</div></section>`}`}
let posFrame=0,inventoryFrame=0;
function schedulePosPaint(){cancelAnimationFrame(posFrame);posFrame=requestAnimationFrame(paintPos)}
function scheduleInventoryPaint(){cancelAnimationFrame(inventoryFrame);inventoryFrame=requestAnimationFrame(()=>renderInventory(false))}
document.addEventListener("click",event=>{const add=event.target.closest("[data-add]"),quantity=event.target.closest("[data-inc],[data-dec]"),posCategory=event.target.closest("[data-pos-category]"),methodButton=event.target.closest("[data-method]");if(add){event.stopPropagation();const product=catalog.products.find(item=>item.id===add.dataset.add),line=cart.find(item=>item.id===product.id);line?line.quantity++:cart.push({...product,quantity:1});return schedulePosPaint()}if(quantity){event.stopPropagation();const id=quantity.dataset.inc||quantity.dataset.dec,line=cart.find(item=>item.id===id);line.quantity+=quantity.dataset.inc?1:-1;if(line.quantity<1)cart=cart.filter(item=>item!==line);return schedulePosPaint()}if(posCategory){event.stopPropagation();category=posCategory.dataset.posCategory;return schedulePosPaint()}if(methodButton){event.stopPropagation();method=methodButton.dataset.method;return schedulePosPaint()}},true);
document.addEventListener("input",event=>{if(event.target.id==="posSearch"){event.stopPropagation();query=event.target.value.toLocaleLowerCase();return schedulePosPaint()}if(event.target.id==="inventorySearch"){event.stopPropagation();inventoryQuery=event.target.value.toLocaleLowerCase();return scheduleInventoryPaint()}},true);
document.addEventListener("click",event=>{if(event.target.closest("[data-cash],#charge"))setTimeout(()=>renderPos(true),600);if(event.target.closest("[data-restock],[data-edit-ingredient]"))setTimeout(()=>renderInventory(true),600)});
document.addEventListener("submit",event=>{if(event.target.matches("#productForm,#ingredientForm"))setTimeout(()=>renderInventory(true),700)});
api("/api/auth/me").then(render).catch(()=>{localStorage.removeItem("cheers_session");location.replace("/login.html")});

/* V6 · cuentas acumuladas por mesa y clientes que pagan después. */
labels.accounts="Cuentas y fiados.";
document.querySelector(".admin-nav nav")?.insertAdjacentHTML("beforeend",'<button class="nav-item" data-panel="accounts">Cuentas y fiados</button>');
const renderBeforeV6=render;
async function renderAccounts(){
  const [tables,customers]=await Promise.all([api("/api/tables/accounts"),api("/api/customers")]);
  const open=tables.accounts||[],people=customers.customers||[];
  view.innerHTML=`<section class="inventory-actions"><div><p class="eyebrow">CUENTAS ABIERTAS</p><h2>Mesas por cobrar</h2></div><span>${open.length} mesa(s)</span></section><section class="account-grid">${open.map(account=>`<article class="account-card"><p>MESA ${String(account.tableId).padStart(2,"0")}</p><h3>${escape(account.tableName)}</h3><p>${escape([...new Set(account.orders.map(order=>order.customerName).filter(Boolean))].join(" · ")||"Cliente sin nombre")} · ${account.orders.length} pedido(s)</p><strong>${money.format(account.total)}</strong><button class="primary-button" data-settle-table="${account.tableId}">Cobrar cuenta</button><button class="text-button" data-credit-table="${account.tableId}">Dejar fiado</button></article>`).join("")||'<p class="empty-state">No hay mesas con cuentas pendientes.</p>'}</section><section class="inventory-actions"><div><p class="eyebrow">CLIENTES RECURRENTES</p><h2>Fiados y abonos</h2></div></section><form id="customerForm" class="quick-form"><strong>Crear cliente fiado</strong><input name="name" maxlength="80" placeholder="Nombre completo" required><input name="phone" maxlength="30" placeholder="Teléfono"><input name="creditLimit" type="number" min="0" placeholder="Cupo máximo (opcional)"><textarea name="notes" maxlength="300" placeholder="Nota interna"></textarea><button class="primary-button">Guardar cliente</button></form><section class="admin-section"><div class="admin-section-head"><h2>Estado de clientes</h2><span>${people.length} registrado(s)</span></div><div class="data-list">${people.map(person=>`<div class="data-row"><div><strong>${escape(person.name)}</strong><span>${escape(person.phone||"Sin teléfono")} · Cupo ${person.creditLimit?money.format(person.creditLimit):"sin límite"}${person.notes?` · ${escape(person.notes)}`:""}</span></div><div class="credit-summary"><strong class="${person.balance>0?"credit-balance":"stock-ok"}">${money.format(person.balance)}</strong>${person.balance>0?`<button class="text-button" data-customer-payment="${person.id}">Abono</button>`:""}<button class="text-button" data-edit-customer="${person.id}">Editar</button></div></div>`).join("")||'<p class="empty-state">Aún no hay clientes fiados.</p>'}</div></section>`;
}
render=async function(){setNav();if(panel==="accounts")return renderAccounts();return renderBeforeV6()};
document.addEventListener("click",async event=>{try{
  const settle=event.target.closest("[data-settle-table]");if(settle){const method=prompt("Medio de pago: Efectivo, Tarjeta, Nequi o Transferencia","Efectivo");if(!method)return;const result=await api(`/api/tables/${settle.dataset.settleTable}/settle`,{method:"POST",body:JSON.stringify({method})});alert(`Cuenta de ${result.settlement.tableName} cobrada: ${money.format(result.settlement.total)}.`);return renderAccounts()}
  const credit=event.target.closest("[data-credit-table]");if(credit){const data=await api("/api/customers"),active=data.customers.filter(person=>person.active);if(!active.length)throw new Error("Primero crea un cliente fiado.");const choice=prompt(`Cliente fiado:\n${active.map((person,index)=>`${index+1}. ${person.name} · debe ${money.format(person.balance)}`).join("\n")}\n\nEscribe el número:`);const person=active[Number(choice)-1];if(!person)return;const result=await api(`/api/tables/${credit.dataset.creditTable}/settle`,{method:"POST",body:JSON.stringify({mode:"credit",customerId:person.id})});alert(`Cuenta dejada fiada a ${result.settlement.customer.name}: ${money.format(result.settlement.total)}.`);return renderAccounts()}
  const pay=event.target.closest("[data-customer-payment]");if(pay){const amount=prompt("Valor del abono:");if(amount===null)return;const method=prompt("Medio de pago:","Efectivo")||"Efectivo";await api(`/api/customers/${pay.dataset.customerPayment}/payment`,{method:"PATCH",body:JSON.stringify({amount,method})});return renderAccounts()}
  const edit=event.target.closest("[data-edit-customer]");if(edit){const data=await api("/api/customers"),person=data.customers.find(item=>item.id===edit.dataset.editCustomer);if(!person)return;const phone=prompt("Teléfono:",person.phone||"");if(phone===null)return;const creditLimit=prompt("Cupo máximo (0 = sin límite):",person.creditLimit||0);if(creditLimit===null)return;await api(`/api/customers/${person.id}`,{method:"PATCH",body:JSON.stringify({...person,phone,creditLimit})});return renderAccounts()}
}catch(error){alert(error.message)}},true);
document.addEventListener("submit",async event=>{if(event.target.id!=="customerForm")return;event.preventDefault();try{const data=Object.fromEntries(new FormData(event.target));await api("/api/customers",{method:"POST",body:JSON.stringify(data)});event.target.reset();renderAccounts()}catch(error){alert(error.message)}});

/* V6.2 · crédito desde caja e historial claro de cada cuenta. */
let creditCustomers=[],creditCustomerId="";
const paintPosBeforeV62=paintPos;
paintPos=function(){
  paintPosBeforeV62();
  const methods=view.querySelector(".method-grid"),ticket=view.querySelector(".pos-ticket");
  if(!methods||!ticket)return;
  methods.insertAdjacentHTML("beforeend",`<button class="method-button ${method==="Fiado"?"active":""}" data-method="Fiado">Fiado</button>`);
  if(method==="Fiado"){
    const options=creditCustomers.filter(person=>person.active).map(person=>`<option value="${person.id}" ${creditCustomerId===person.id?"selected":""}>${escape(person.name)} · debe ${money.format(person.balance)}</option>`).join("");
    ticket.querySelector("#charge")?.insertAdjacentHTML("beforebegin",`<label class="credit-picker">Cliente para fiar<select id="posCreditCustomer"><option value="">${options?"Selecciona un cliente":"Cargando clientes…"}</option>${options}</select></label>`);
  }
};
document.addEventListener("click",event=>{
  if(!event.target.closest('[data-method="Fiado"]'))return;
  api("/api/customers").then(data=>{creditCustomers=data.customers||[];schedulePosPaint()}).catch(error=>alert(error.message));
},true);
document.addEventListener("change",event=>{if(event.target.id==="posCreditCustomer")creditCustomerId=event.target.value},true);
document.addEventListener("click",async event=>{
  const charge=event.target.closest("#charge");
  if(!charge||method!=="Fiado")return;
  event.preventDefault();event.stopImmediatePropagation();
  if(!creditCustomerId)return alert("Selecciona el cliente al que se le dejará fiado.");
  try{
    const person=creditCustomers.find(item=>item.id===creditCustomerId);
    const order=await api("/api/pos/sale",{method:"POST",body:JSON.stringify({method:"Fiado",customerId:creditCustomerId,customerName:person?.name||"",items:cart.map(item=>({productId:item.id,quantity:item.quantity}))})});
    cart=[];alert(`Factura ${order.order.code} dejada fiada a ${person?.name||"cliente"}.`);openInvoice(order.order);renderPos(true);
  }catch(error){alert(error.message)}
},true);
function debtDays(date){if(!date)return 0;return Math.max(0,Math.floor((Date.now()-new Date(date).getTime())/86400000))}
renderAccounts=async function(){
  const [tables,customers]=await Promise.all([api("/api/tables/accounts"),api("/api/customers")]);
  const open=tables.accounts||[],people=customers.customers||[];
  const clients=people.map(person=>{const invoices=(person.movements||[]).filter(move=>move.kind==="charge"),days=person.balance>0?debtDays(person.debtSince):0;return `<article class="account-card credit-account"><div class="credit-title"><div><h3>${escape(person.name)}</h3><p>${escape(person.phone||"Sin teléfono")} · Cupo ${person.creditLimit?money.format(person.creditLimit):"sin límite"}</p></div><strong class="${person.balance>0?"credit-balance":"stock-ok"}">${money.format(person.balance)}</strong></div><p class="debt-age">${person.balance>0?`Pendiente hace ${days} día${days===1?"":"s"}`:"Sin saldo pendiente"}</p><div class="credit-invoices">${invoices.slice(0,6).map(move=>`<div><span>${escape(move.orderCode||"Cargo")}</span><small>${new Date(move.createdAt).toLocaleDateString("es-CO")} · ${escape(move.method||"Fiado")}</small><b>${money.format(move.amount)}</b></div>`).join("")||"<small>Sin facturas fiadas todavía.</small>"}</div><div class="credit-summary">${person.balance>0?`<button class="text-button" data-customer-payment="${person.id}">Registrar abono</button>`:""}<button class="text-button" data-edit-customer="${person.id}">Editar</button></div></article>`}).join("")||'<p class="empty-state">Aún no hay clientes fiados.</p>';
  view.innerHTML=`<section class="inventory-actions"><div><p class="eyebrow">CUENTAS ABIERTAS</p><h2>Mesas por cobrar</h2></div><span>${open.length} mesa(s)</span></section><section class="account-grid">${open.map(account=>`<article class="account-card"><p>MESA ${String(account.tableId).padStart(2,"0")}</p><h3>${escape(account.tableName)}</h3><p>${escape([...new Set(account.orders.map(order=>order.customerName).filter(Boolean))].join(" · ")||"Cliente sin nombre")} · ${account.orders.length} pedido(s)</p><strong>${money.format(account.total)}</strong><button class="primary-button" data-settle-table="${account.tableId}">Cobrar cuenta</button><button class="text-button" data-credit-table="${account.tableId}">Dejar fiado</button></article>`).join("")||'<p class="empty-state">No hay mesas con cuentas pendientes.</p>'}</section><section class="inventory-actions"><div><p class="eyebrow">CLIENTES RECURRENTES</p><h2>Fiados, abonos e historial</h2></div><span>${people.filter(person=>person.balance>0).length} con saldo</span></section><form id="customerForm" class="quick-form"><strong>Crear cliente fiado</strong><input name="name" maxlength="80" placeholder="Nombre completo" required><input name="phone" maxlength="30" placeholder="Teléfono"><input name="creditLimit" type="number" min="0" placeholder="Cupo máximo (opcional)"><textarea name="notes" maxlength="300" placeholder="Nota interna"></textarea><button class="primary-button">Guardar cliente</button></form><section class="account-grid credit-client-grid">${clients}</section>`;
};

/* V7.1 · un fiado es una cuenta por cobrar, no dinero recibido. */
let creditSettlementCustomers=[],creditSettlementId="",creditSettlementAmount="",creditSettlementMethod="Efectivo",creditSettlementLoadedAt=0;
const renderPosBeforeV71=renderPos;
renderPos=async function(force=false){
  await renderPosBeforeV71(force);
  if(force||Date.now()-creditSettlementLoadedAt>30_000){
    try{const data=await api("/api/customers");creditSettlementCustomers=data.customers||[];creditSettlementLoadedAt=Date.now();paintPos()}catch(error){console.warn("No se pudieron cargar los fiados",error)}
  }
};
const paintPosBeforeV71=paintPos;
paintPos=function(){
  paintPosBeforeV71();
  const ticket=view.querySelector(".pos-ticket");if(!ticket)return;
  const people=creditSettlementCustomers.filter(person=>person.balance>0),selected=people.find(person=>person.id===creditSettlementId)||people[0];
  if(selected&&!creditSettlementId)creditSettlementId=selected.id;
  const amount=creditSettlementAmount||selected?.balance||"";
  ticket.insertAdjacentHTML("beforeend",`<section class="credit-settlement"><div class="credit-settlement-head"><div><p class="eyebrow">COBRAR FIADOS</p><strong>Cuenta pendiente</strong></div><span>${people.length?`${people.length} cliente${people.length===1?"":"s"}`:"Al día"}</span></div>${people.length?`<label>Cliente<select id="creditSettlementCustomer">${people.map(person=>`<option value="${person.id}" ${person.id===creditSettlementId?"selected":""}>${escape(person.name)} · ${money.format(person.balance)}</option>`).join("")}</select></label><div class="credit-settlement-fields"><label>Pago<input id="creditSettlementAmount" inputmode="numeric" type="number" min="1" max="${selected.balance}" value="${escape(amount)}"></label><label>Medio<select id="creditSettlementMethod">${["Efectivo","Tarjeta","Nequi","Transferencia"].map(item=>`<option ${creditSettlementMethod===item?"selected":""}>${item}</option>`).join("")}</select></label></div><button class="credit-settlement-button" data-settle-credit="${selected.id}">Cobrar ${money.format(selected.balance)} completo</button><small>También puedes registrar un abono menor en el campo de pago.</small>`:`<p class="credit-settlement-empty">No hay fiados pendientes por cobrar.</p>`}</section>`);
};
document.addEventListener("change",event=>{
  if(event.target.id==="creditSettlementCustomer"){creditSettlementId=event.target.value;creditSettlementAmount="";schedulePosPaint()}
  if(event.target.id==="creditSettlementAmount")creditSettlementAmount=event.target.value;
  if(event.target.id==="creditSettlementMethod")creditSettlementMethod=event.target.value;
},true);
document.addEventListener("click",async event=>{
  const button=event.target.closest("[data-settle-credit]");if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  const person=creditSettlementCustomers.find(item=>item.id===button.dataset.settleCredit);if(!person)return alert("Actualiza la caja e intenta de nuevo.");
  const amount=Math.min(Number(creditSettlementAmount)||Number(person.balance),Number(person.balance));
  if(!amount||amount<=0)return alert("Escribe un valor válido para cobrar.");
  try{await api(`/api/customers/${person.id}/payment`,{method:"PATCH",body:JSON.stringify({amount,method:creditSettlementMethod,note:"Cobro desde caja"})});alert(`${amount===Number(person.balance)?"Deuda cancelada":"Abono registrado"} de ${person.name}: ${money.format(amount)}.`);creditSettlementAmount="";creditSettlementId="";creditSettlementLoadedAt=0;renderPos(true)}catch(error){alert(error.message)}
},true);

/* V7.5 · cuentas abiertas desde caja: cada mesa acumula pedidos y se cobra al final. */
let posAccounts=[],posMode="quick",posAccountTableId="",posAccountName="",posAccountsUpdated=0;
async function refreshPosAccounts(force=false){if(force||!posAccountsUpdated||Date.now()-posAccountsUpdated>15000){const data=await api("/api/tables/accounts");posAccounts=data.accounts||[];posAccountsUpdated=Date.now()}}
function accountForTable(id){return posAccounts.find(account=>Number(account.tableId)===Number(id))}
function switchPosMode(mode,tableId="",name=""){
  if(cart.length){alert("Primero guarda este pedido o quita los productos antes de cambiar de cuenta.");return false}
  cart=[];posMode=mode;posAccountTableId=tableId?String(tableId):"";posAccountName=name||"";return true;
}
const paintPosBeforeV75=paintPos;
paintPos=function(){
  paintPosBeforeV75();
  const catalogBox=view.querySelector(".pos-catalog"),ticket=view.querySelector(".pos-ticket");if(!catalogBox||!ticket)return;
  const account=posMode==="account"?accountForTable(posAccountTableId):null;
  const tabs=[`<button class="pos-account-tab ${posMode==="quick"?"active":""}" data-pos-mode="quick">Venta rápida</button>`,...posAccounts.map(item=>{const customer=String(item.orders.find(order=>order.customerName)?.customerName||"").trim(),label=customer||`Mesa ${String(item.tableId).padStart(2,"0")}`,reference=customer?`Mesa ${String(item.tableId).padStart(2,"0")} · ${money.format(item.total)}`:money.format(item.total);return `<button class="pos-account-tab ${posMode==="account"&&Number(posAccountTableId)===Number(item.tableId)?"active":""}" data-pos-mode="account" data-pos-account="${item.tableId}">${escape(label)}<small>${escape(reference)}</small></button>`}),`<button class="pos-account-tab pos-account-new ${posMode==="new"?"active":""}" data-pos-mode="new">＋ Abrir cuenta</button>`].join("");
  catalogBox.insertAdjacentHTML("afterbegin",`<section class="pos-accounts"><div class="pos-accounts-head"><div><p class="eyebrow">CUENTAS EN CURSO</p><strong>${posAccounts.length?`${posAccounts.length} abierta${posAccounts.length===1?"":"s"}`:"Sin cuentas abiertas"}</strong></div><small>Guarda pedidos y cobra al final</small></div><div class="pos-account-tabs">${tabs}</div></section>`);
  const existingTotal=account?Number(account.total)||0:0, draftTotal=cart.reduce((sum,item)=>sum+item.price*item.quantity,0);
  if(posMode==="quick")return;
  const tableOptions=(catalog.tables||[]).map(table=>`<option value="${table.id}" ${String(table.id)===String(posAccountTableId)?"selected":""}>${escape(table.name||`Mesa ${String(table.id).padStart(2,"0")}`)}</option>`).join("");
  const heading=posMode==="new"?"Abrir cuenta":"Cuenta abierta";
  const tableName=posMode==="new"?"Nueva mesa":account?.tableName||`Mesa ${String(posAccountTableId).padStart(2,"0")}`;
  const customer=posAccountName||account?.orders?.map(order=>order.customerName).find(Boolean)||"";
  ticket.innerHTML=`<p class="eyebrow">${heading}</p><h2>${escape(tableName)}</h2><div class="account-ticket-info">${posMode==="new"?`<label>Mesa<select id="posAccountTable">${tableOptions}</select></label>`:`<div><span>Pedidos guardados</span><strong>${account?.orders?.length||0}</strong></div>`}<label>Nombre del cliente <input id="posAccountName" maxlength="60" value="${escape(customer)}" placeholder="Opcional"></label></div><div class="pos-cart">${cart.map(item=>`<div class="pos-line"><div><b>${escape(item.name)}</b><small>${money.format(item.price)}</small></div><div class="pos-qty"><button data-dec="${item.id}">−</button><span>${item.quantity}</span><button data-inc="${item.id}">+</button></div><strong>${money.format(item.price*item.quantity)}</strong></div>`).join("")||'<p class="empty-state">Agrega productos a esta cuenta. Puedes seguir guardando rondas durante la visita.</p>'}</div><div class="account-totals"><div><span>Ya guardado</span><strong>${money.format(existingTotal)}</strong></div><div><span>Esta ronda</span><strong>${money.format(draftTotal)}</strong></div></div><button class="checkout-button account-save" id="saveOpenOrder" ${cart.length?"":"disabled"}>${posMode==="new"?"Abrir cuenta y guardar pedido":"Guardar pedido en cuenta"}</button>${account?`<div class="pos-total"><span>Total de la mesa</span><strong>${money.format(existingTotal+draftTotal)}</strong></div><p class="eyebrow">Cobrar cuenta completa</p><div class="method-grid">${["Efectivo","Tarjeta","Nequi","Transferencia"].map(item=>`<button class="method-button ${method===item?"active":""}" data-method="${item}">${item}</button>`).join("")}</div><button class="checkout-button" id="settleOpenAccount" ${account&&posMeta.cash.session?"":"disabled"}>${posMeta.cash.session?"Cobrar cuenta y facturar":"Abre caja para cobrar"}</button>`:""}<button class="text-button pos-return-quick" data-pos-mode="quick">Volver a venta rápida</button>`;
};
const renderPosBeforeV75=renderPos;
renderPos=async function(force=false){await renderPosBeforeV75(force);await refreshPosAccounts(force);paintPos()};
document.addEventListener("click",async event=>{try{
  const tab=event.target.closest("[data-pos-mode]");
  if(tab){event.preventDefault();event.stopImmediatePropagation();const mode=tab.dataset.posMode,account=mode==="account"?accountForTable(tab.dataset.posAccount):null;if(switchPosMode(mode,tab.dataset.posAccount,account?.orders?.map(order=>order.customerName).find(Boolean)||""))paintPos();return}
  const save=event.target.closest("#saveOpenOrder");
  if(save){event.preventDefault();event.stopImmediatePropagation();const tableId=Number(posAccountTableId);if(!tableId)return alert("Selecciona una mesa.");const result=await api("/api/pos/open-order",{method:"POST",body:JSON.stringify({tableId,customerName:posAccountName,items:cart.map(item=>({productId:item.id,quantity:item.quantity}))})});cart=[];posMode="account";posAccountTableId=String(tableId);posAccountName=result.order.customerName||posAccountName;posAccountsUpdated=0;alert(`Pedido ${result.order.code} guardado en Mesa ${String(tableId).padStart(2,"0")}. Puedes seguir agregando productos o cobrar al final.`);return renderPos(true)}
  const settle=event.target.closest("#settleOpenAccount");
  if(settle){event.preventDefault();event.stopImmediatePropagation();const tableId=Number(posAccountTableId),account=accountForTable(tableId);if(!account)return alert("Actualiza la cuenta e intenta de nuevo.");if(cart.length)return alert("Primero guarda esta ronda en la cuenta.");const result=await api(`/api/tables/${tableId}/settle`,{method:"POST",body:JSON.stringify({method})});alert(`Cuenta de ${result.settlement.tableName} cobrada: ${money.format(result.settlement.total)}.`);posMode="quick";posAccountTableId="";posAccountName="";posAccountsUpdated=0;return renderPos(true)}
}catch(error){alert(error.message)}},true);
document.addEventListener("input",event=>{if(event.target.id==="posAccountName")posAccountName=event.target.value},true);
document.addEventListener("change",event=>{if(event.target.id==="posAccountTable"){posAccountTableId=event.target.value;paintPos()}},true);

/* V7.5.1 · sin ventanas nativas: abrir/cerrar caja funciona en tablet y navegador integrado. */
let cashAction="";
function showCashForm(action){cashAction=action;const dialog=document.createElement("div");dialog.className="cheers-modal";dialog.id="cashModal";dialog.innerHTML=`<form class="cheers-modal-card" id="cashForm"><button type="button" class="modal-close" data-close-cash aria-label="Cerrar">×</button><p class="eyebrow">TURNO DE CAJA</p><h2>${action==="open"?"Abrir turno":"Cerrar turno"}</h2><p>${action==="open"?"Registra el fondo inicial para comenzar a facturar.":"Registra el efectivo contado para cerrar el turno."}</p><label>${action==="open"?"Fondo inicial":"Efectivo contado"}<input id="cashAmount" name="amount" inputmode="decimal" type="number" min="0" step="1" placeholder="$ 0" required autofocus></label><button class="checkout-button">${action==="open"?"Abrir caja":"Cerrar y ver resumen"}</button></form>`;document.body.append(dialog);requestAnimationFrame(()=>dialog.classList.add("open"))}
document.addEventListener("click",event=>{const cash=event.target.closest("[data-cash]");if(cash){event.preventDefault();event.stopImmediatePropagation();showCashForm(cash.dataset.cash);return}if(event.target.closest("[data-close-cash]")){event.preventDefault();document.querySelector("#cashModal")?.remove()}},true);
document.addEventListener("submit",async event=>{if(event.target.id!=="cashForm")return;event.preventDefault();try{const result=await api(`/api/cash/${cashAction}`,{method:"POST",body:JSON.stringify({amount:new FormData(event.target).get("amount")})});document.querySelector("#cashModal")?.remove();if(result.summary)alert(`Esperado: ${money.format(result.summary.expected)}\\nContado: ${money.format(result.summary.counted)}\\nDiferencia: ${money.format(result.summary.difference)}`);renderPos(true)}catch(error){alert(error.message)}},true);
const renderSalesBeforeV71=renderSales;
renderSales=async function(){
  const report=await api("/api/reports/sales"),collections=report.creditCollections||[];
  view.innerHTML=`<div class="metric-grid"><article><span>Recibido hoy</span><strong>${money.format(report.today)}</strong></article><article><span>Recibido semana</span><strong>${money.format(report.week)}</strong></article><article><span>Recibido mes</span><strong>${money.format(report.month)}</strong></article><article><span>Facturas</span><strong>${report.invoices.length}</strong></article></div><section class="admin-section"><div class="admin-section-head"><h2>Facturas creadas</h2><span>Fiado no suma hasta cobrarse</span></div><div class="data-list">${report.invoices.map(invoice=>`<div class="data-row"><div><strong>${escape(invoice.order.code)}</strong><span>${escape(invoice.order.items.map(item=>`${item.quantity}× ${item.name}`).join(", "))} · ${escape(invoice.method)}${invoice.method==="Fiado"?" · pendiente de cobro":""}</span></div><div><strong>${money.format(invoice.amount)}</strong><button class="text-button" data-print-invoice="${invoice.order.id}">Imprimir</button><button class="text-button" data-cancel-sale="${invoice.order.id}">Anular</button></div></div>`).join("")||'<p class="empty-state">Todavía no hay facturas.</p>'}</div></section>${collections.length?`<section class="admin-section"><div class="admin-section-head"><h2>Abonos recibidos</h2><span>Estos sí suman a caja y ventas</span></div><div class="data-list">${collections.slice(0,20).map(item=>`<div class="data-row"><div><strong>${escape(item.customerName)}</strong><span>${escape(item.method)} · ${new Date(item.createdAt).toLocaleDateString("es-CO")}</span></div><strong>${money.format(item.amount)}</strong></div>`).join("")}</div></section>`:""}`;
};

/* El personal ve nuevas cuentas y pedidos sin tener que recargar la página. */
let liveRefreshBusy=false;
async function refreshLivePanel(){
  if(liveRefreshBusy||document.hidden||!['accounts','dashboard','tables'].includes(panel))return;
  const active=document.activeElement;
  if(active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName))return;
  liveRefreshBusy=true;
  try{await render()}catch(error){console.warn('Actualización en segundo plano no disponible',error)}finally{liveRefreshBusy=false}
}
setInterval(refreshLivePanel,12000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshLivePanel()});

/* V7.5.2 · todos los formularios administrativos son internos, sin prompt/confirm nativos. */
function askAdminForm({title,copy="",fields=[],submit="Guardar",danger=false}){return new Promise(resolve=>{const modal=document.createElement("div");modal.className="cheers-modal";modal.id="adminActionModal";const controls=fields.map(field=>{const options=(field.options||[]).map(option=>`<option value="${escape(String(option.value))}" ${String(option.value)===String(field.value??"")?"selected":""}>${escape(option.label)}</option>`).join("");const control=field.type==="select"?`<select name="${escape(field.name)}" ${field.required?"required":""}>${options}</select>`:`<input name="${escape(field.name)}" type="${field.type||"text"}" value="${escape(String(field.value??""))}" ${field.min!==undefined?`min="${field.min}"`:""} ${field.step?`step="${field.step}"`:""} ${field.required?"required":""} ${field.placeholder?`placeholder="${escape(field.placeholder)}"`:""}>`;return `<label>${escape(field.label)}${control}</label>`}).join("");modal.innerHTML=`<form class="cheers-modal-card"><button type="button" class="modal-close" aria-label="Cerrar">×</button><p class="eyebrow">CHEERS CENTRAL</p><h2>${escape(title)}</h2>${copy?`<p>${escape(copy)}</p>`:""}<div class="admin-modal-fields">${controls}</div><button class="${danger?"danger-button":"checkout-button"}">${escape(submit)}</button></form>`;const close=value=>{modal.remove();resolve(value)};modal.querySelector(".modal-close").addEventListener("click",()=>close(null));modal.addEventListener("click",event=>{if(event.target===modal)close(null)});modal.querySelector("form").addEventListener("submit",event=>{event.preventDefault();close(Object.fromEntries(new FormData(event.currentTarget)))});document.body.append(modal);requestAnimationFrame(()=>modal.classList.add("open"))})}
function askAdminConfirm(title,copy,submit="Continuar"){return askAdminForm({title,copy,submit,danger:true})}
window.addEventListener("click",async event=>{const target=event.target;
  const restock=target.closest("[data-restock]");const editIngredient=target.closest("[data-edit-ingredient]");const cancelSale=target.closest("[data-cancel-sale]");const settleTable=target.closest("[data-settle-table]");const creditTable=target.closest("[data-credit-table]");const customerPayment=target.closest("[data-customer-payment]");const editCustomer=target.closest("[data-edit-customer]");
  if(!restock&&!editIngredient&&!cancelSale&&!settleTable&&!creditTable&&!customerPayment&&!editCustomer)return;
  event.preventDefault();event.stopImmediatePropagation();
  try{
    if(restock){const ingredient=catalog.inventory.find(item=>item.id===restock.dataset.restock),answer=await askAdminForm({title:"Registrar entrada",copy:ingredient?`${ingredient.name} · existencia actual: ${ingredient.stock}`:"",fields:[{name:"quantity",label:"Cantidad que ingresó",type:"number",min:1,step:"any",required:true}],submit:"Agregar al inventario"});if(answer)await api(`/api/inventory/${ingredient.id}/restock`,{method:"PATCH",body:JSON.stringify({quantity:answer.quantity})});return renderInventory()}
    if(editIngredient){const ingredient=catalog.inventory.find(item=>item.id===editIngredient.dataset.editIngredient),answer=await askAdminForm({title:"Ajustar inventario",copy:ingredient?.name||"",fields:[{name:"stock",label:`Existencia en ${ingredient?.unit||"unidades"}`,type:"number",min:0,step:"any",value:ingredient?.stock??0,required:true}],submit:"Guardar ajuste"});if(answer)await api(`/api/inventory/${ingredient.id}`,{method:"PATCH",body:JSON.stringify({...ingredient,stock:answer.stock})});return renderInventory()}
    if(cancelSale){const answer=await askAdminConfirm("Anular venta","Se devolverá el inventario de esta factura. Esta acción queda registrada.","Anular venta");if(answer)await api(`/api/orders/${cancelSale.dataset.cancelSale}/status`,{method:"PATCH",body:JSON.stringify({status:"cancelled"})});return renderSales()}
    if(settleTable){const answer=await askAdminForm({title:"Cobrar cuenta",copy:"Selecciona cómo pagó el cliente.",fields:[{name:"method",label:"Medio de pago",type:"select",value:"Efectivo",options:["Efectivo","Tarjeta","Nequi","Transferencia"].map(value=>({value,label:value}))}],submit:"Cobrar cuenta"});if(!answer)return;const result=await api(`/api/tables/${settleTable.dataset.settleTable}/settle`,{method:"POST",body:JSON.stringify(answer)});alert(`Cuenta de ${result.settlement.tableName} cobrada: ${money.format(result.settlement.total)}.`);return renderAccounts()}
    if(creditTable){const data=await api("/api/customers"),active=data.customers.filter(person=>person.active);if(!active.length)throw new Error("Primero crea un cliente fiado.");const answer=await askAdminForm({title:"Dejar cuenta fiada",copy:"El saldo quedará a nombre del cliente seleccionado.",fields:[{name:"customerId",label:"Cliente",type:"select",required:true,options:active.map(person=>({value:person.id,label:`${person.name} · debe ${money.format(person.balance)}`}))}],submit:"Dejar fiado"});if(!answer)return;const result=await api(`/api/tables/${creditTable.dataset.creditTable}/settle`,{method:"POST",body:JSON.stringify({mode:"credit",customerId:answer.customerId})});alert(`Cuenta dejada fiada a ${result.settlement.customer.name}: ${money.format(result.settlement.total)}.`);return renderAccounts()}
    if(customerPayment){const answer=await askAdminForm({title:"Registrar abono",copy:"Este pago reduce la deuda y sí cuenta como dinero recibido.",fields:[{name:"amount",label:"Valor del abono",type:"number",min:1,step:"1",required:true},{name:"method",label:"Medio de pago",type:"select",value:"Efectivo",options:["Efectivo","Tarjeta","Nequi","Transferencia"].map(value=>({value,label:value}))}],submit:"Guardar abono"});if(answer)await api(`/api/customers/${customerPayment.dataset.customerPayment}/payment`,{method:"PATCH",body:JSON.stringify(answer)});return renderAccounts()}
    if(editCustomer){const data=await api("/api/customers"),person=data.customers.find(item=>item.id===editCustomer.dataset.editCustomer);if(!person)return;const answer=await askAdminForm({title:"Editar cliente",fields:[{name:"phone",label:"Teléfono",value:person.phone||"",placeholder:"Opcional"},{name:"creditLimit",label:"Cupo máximo",type:"number",min:0,step:"1",value:person.creditLimit||0,required:true}],submit:"Guardar cambios"});if(answer)await api(`/api/customers/${person.id}`,{method:"PATCH",body:JSON.stringify({...person,...answer})});return renderAccounts()}
  }catch(error){alert(error.message)}
},true);
